import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
def extract(d):
    result = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result
base = extract(b)
after = extract(a)
if base == after:
    print('IDENTICAL - all packages resolve to same versions')
else:
    for k in set(list(base.keys()) + list(after.keys())):
        bv = base.get(k)
        av = after.get(k)
        if bv != av:
            print(f'DIFF: {k}: {bv} -> {av}')
"

